// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;

import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    RoundFactory c;

    function setUp() public {
        c = new RoundFactory();
    }

    function _run(address newAlloSettings) internal {
        bool initOk;
        try c.initialize() { initOk = true; } catch { initOk = false; }
        bool setOk;
        try c.updateAlloSettings(newAlloSettings) { setOk = true; } catch { setOk = false; }
        assertTrue(setOk == initOk && (!setOk || c.alloSettings() == newAlloSettings));
    }

    function testFuzz_run(address newAlloSettings) public {
        vm.assume(newAlloSettings.code.length == 0 && uint160(newAlloSettings) > 0xffff && newAlloSettings != address(this) && newAlloSettings != address(c) && newAlloSettings != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && newAlloSettings != 0x000000000000000000636F6e736F6c652e6c6f67 && newAlloSettings != 0x4e59b44847b379578588920cA78FbF26c0B4956C && newAlloSettings != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(newAlloSettings);
    }

    receive() external payable {}
}
